/**
 * Venya WebAuthn client wrapper.
 *
 * Thin wrapper around the browser's native WebAuthn API
 * (navigator.credentials) for use in enrollment and login flows.
 */
var VenyaWebAuthn = (function () {
    "use strict";

    /**
     * Convert base64url string to Uint8Array.
     */
    function base64urlToArray(b64url) {
        var padding = "=".repeat((4 - (b64url.length % 4)) % 4);
        var base64 = b64url.replace(/-/g, "+").replace(/_/g, "/") + padding;
        var binary = atob(base64);
        var len = binary.length;
        var bytes = new Uint8Array(len);
        for (var i = 0; i < len; i++) {
            bytes[i] = binary.charCodeAt(i);
        }
        return bytes;
    }

    /**
     * Convert Uint8Array or ArrayBuffer to base64url string.
     */
    function arrayToBase64url(bytes) {
        // Handle ArrayBuffer by wrapping in Uint8Array
        // Use Object.prototype.toString for cross-realm safety
        if (Object.prototype.toString.call(bytes) === "[object ArrayBuffer]") {
            bytes = new Uint8Array(bytes);
        }
        var binary = "";
        var len = bytes.byteLength || bytes.length;
        for (var i = 0; i < len; i++) {
            binary += String.fromCharCode(bytes[i]);
        }
        return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
    }

    /**
     * Start WebAuthn registration (create a new credential).
     * @param {object} options - PublicKeyCredentialCreationOptions from server.
     * @returns {object} Attestation response.
     */
    async function startRegistration(options) {
        // Convert base64url challenge to Uint8Array
        var challenge = base64urlToArray(options.challenge);

        // Save original user.id (base64url string) for response
        var originalUserId = options.user.id;

        // Convert user.id from base64url to Uint8Array
        var user = options.user;
        user.id = base64urlToArray(user.id);

        // Convert excludeCredentials.id from base64url to Uint8Array
        if (options.excludeCredentials) {
            for (var i = 0; i < options.excludeCredentials.length; i++) {
                options.excludeCredentials[i].id = base64urlToArray(
                    options.excludeCredentials[i].id
                );
            }
        }

        var publicKey = {
            challenge: challenge,
            rp: options.rp,
            user: user,
            pubKeyCredParams: options.pubKeyCredParams,
        };

        if (options.timeout) publicKey.timeout = options.timeout;
        if (options.excludeCredentials)
            publicKey.excludeCredentials = options.excludeCredentials;
        if (options.authenticatorSelection)
            publicKey.authenticatorSelection =
                options.authenticatorSelection;
        if (options.attestation) publicKey.attestation = options.attestation;

        var cred = await navigator.credentials.create({
            publicKey: publicKey,
        });

        var authAttestation = cred.response;

        // Debug logging
        console.log("WebAuthn registration response:", {
            clientDataJSON: authAttestation.clientDataJSON?.constructor?.name,
            attestationObject: authAttestation.attestationObject?.constructor?.name,
            hasGetMethod: typeof authAttestation.getAuthenticatorData === "function",
        });

        var clientDataB64 = arrayToBase64url(authAttestation.clientDataJSON);
        var attestationB64 = arrayToBase64url(authAttestation.attestationObject);

        console.log("Converted to base64url:", {
            clientDataJSON: clientDataB64?.substring(0, 20) + "...",
            attestationObject: attestationB64?.substring(0, 20) + "...",
        });

        return {
            id: originalUserId,
            rawId: arrayToBase64url(cred.rawId),
            response: {
                clientDataJSON: clientDataB64,
                attestationObject: attestationB64,
            },
            type: "public-key",
            authenticatorAttachment: cred.authenticatorAttachment,
        };
    }

    /**
     * Start WebAuthn authentication (assertion).
     * @param {object} options - PublicKeyCredentialRequestOptions from server.
     * @returns {object} Assertion response.
     */
    async function startAuthentication(options) {
        // Convert base64url challenge to Uint8Array
        var challenge = base64urlToArray(options.challenge);

        var publicKey = {
            challenge: challenge,
            rpId: options.rpId || options.rp?.id,
        };

        if (options.allowCredentials) {
            publicKey.allowCredentials = options.allowCredentials.map(
                function (c) {
                    return {
                        id: base64urlToArray(c.id),
                        type: c.type,
                        transports: c.transports,
                    };
                }
            );
        }

        if (options.userVerification)
            publicKey.userVerification = options.userVerification;
        if (options.timeout) publicKey.timeout = options.timeout;

        var cred = await navigator.credentials.get({
            publicKey: publicKey,
        });

        var authAssertion = cred.response;

        var result = {
            id: options.allowCredentials
                ? options.allowCredentials[0].id
                : arrayToBase64url(cred.rawId),
            rawId: arrayToBase64url(cred.rawId),
            response: {
                clientDataJSON: arrayToBase64url(authAssertion.clientDataJSON),
                authenticatorData: arrayToBase64url(authAssertion.authenticatorData),
                signature: arrayToBase64url(authAssertion.signature),
            },
            type: "public-key",
            authenticatorAttachment: cred.authenticatorAttachment,
        };

        if (authAssertion.userHandle) {
            result.response.userHandle = arrayToBase64url(authAssertion.userHandle);
        }

        return result;
    }

    return {
        startRegistration: startRegistration,
        startAuthentication: startAuthentication,
    };
})();
